# Validate inputs and assemble the 3D coordinates + colour values used by
# both plot_pca3d() and animate_pca3d().
#
# `color_by` here is already a plain string (or NULL) -- tidy evaluation of
# the user-facing unquoted argument happens in the exported functions.
pca3d_prepare_data <- function(pca, dims, metadata = NULL, color_by = NULL) {
  if (!inherits(pca, "prcomp")) {
    cli::cli_abort("{.arg pca} must be a {.cls prcomp} object, not {.cls {class(pca)}}.")
  }
  if (!is.numeric(dims) || length(dims) != 3) {
    cli::cli_abort("{.arg dims} must be a numeric vector of length 3.")
  }
  if (max(dims) > ncol(pca$x)) {
    cli::cli_abort(
      "{.arg dims} requests PC{max(dims)} but {.arg pca} only has {ncol(pca$x)} components."
    )
  }

  scores <- pca$x[, dims, drop = FALSE]
  colnames(scores) <- c("x", "y", "z")

  color_values <- NULL
  if (!is.null(color_by)) {
    if (is.null(metadata)) {
      cli::cli_abort("{.arg metadata} must be supplied when {.arg color_by} is used.")
    }
    if (nrow(metadata) != nrow(scores)) {
      cli::cli_abort(c(
        "{.arg metadata} must have one row per sample in {.arg pca}.",
        "x" = "{.arg pca} has {nrow(scores)} samples but {.arg metadata} has {nrow(metadata)} rows."
      ))
    }

    scores_rn <- rownames(scores)
    meta_rn <- rownames(metadata)
    has_real_rownames <- function(rn, n) {
      !is.null(rn) && !identical(rn, as.character(seq_len(n)))
    }
    if (has_real_rownames(scores_rn, nrow(scores)) && has_real_rownames(meta_rn, nrow(metadata))) {
      if (!setequal(scores_rn, meta_rn)) {
        cli::cli_abort("Row names of {.arg metadata} do not match sample names in {.arg pca}.")
      }
      metadata <- metadata[scores_rn, , drop = FALSE]
    }

    if (!color_by %in% names(metadata)) {
      cli::cli_abort("{.val {color_by}} not found in {.arg metadata}.")
    }
    color_values <- metadata[[color_by]]
  }

  list(coords = scores, color_values = color_values)
}

# Build the "PC1 (32.1%) · PC2 (20.4%) · PC3 (15.8%)" caption.
pca3d_variance_caption <- function(pca, dims) {
  var_pct <- 100 * pca$sdev^2 / sum(pca$sdev^2)
  parts <- sprintf("PC%d (%.1f%%)", dims, var_pct[dims])
  paste(parts, collapse = " \u00b7 ")
}

make_pca <- function(n = 10, p = 4, rownames_ = NULL) {
  set.seed(3812)
  mat <- matrix(rnorm(n * p), nrow = n, ncol = p)
  if (!is.null(rownames_)) rownames(mat) <- rownames_
  prcomp(mat)
}

test_that("errors if pca is not a prcomp object", {
  expect_error(pca3d_prepare_data(list(), dims = 1:3), class = "rlang_error")
})

test_that("errors if dims isn't length 3", {
  pca <- make_pca()
  expect_error(pca3d_prepare_data(pca, dims = 1:2), class = "rlang_error")
})

test_that("errors if dims exceeds available components", {
  pca <- make_pca(p = 4)
  expect_error(pca3d_prepare_data(pca, dims = c(1, 2, 10)), class = "rlang_error")
})

test_that("returns coords with x, y, z columns for the requested dims", {
  pca <- make_pca()
  out <- pca3d_prepare_data(pca, dims = c(2, 3, 4))
  expect_equal(colnames(out$coords), c("x", "y", "z"))
  expect_equal(unname(out$coords[, "x"]), unname(pca$x[, 2]))
  expect_null(out$color_values)
})

test_that("errors if color_by requested without metadata", {
  pca <- make_pca()
  expect_error(pca3d_prepare_data(pca, dims = 1:3, color_by = "grp"), class = "rlang_error")
})

test_that("errors if metadata row count doesn't match", {
  pca <- make_pca(n = 10)
  metadata <- data.frame(grp = letters[1:5])
  expect_error(
    pca3d_prepare_data(pca, dims = 1:3, metadata = metadata, color_by = "grp"),
    class = "rlang_error"
  )
})

test_that("errors if color_by column not found in metadata", {
  pca <- make_pca(n = 10)
  metadata <- data.frame(grp = letters[1:10])
  expect_error(
    pca3d_prepare_data(pca, dims = 1:3, metadata = metadata, color_by = "nope"),
    class = "rlang_error"
  )
})

test_that("aligns metadata to pca rownames when both have real row names", {
  ids <- paste0("s", 1:10)
  pca <- make_pca(n = 10, rownames_ = ids)
  metadata <- data.frame(grp = ids, val = 1:10, row.names = ids)
  metadata_shuffled <- metadata[sample(nrow(metadata)), , drop = FALSE]

  out <- pca3d_prepare_data(pca, dims = 1:3, metadata = metadata_shuffled, color_by = "val")
  expect_equal(out$color_values, 1:10)
})

test_that("detects continuous vs categorical color_by values", {
  pca <- make_pca(n = 10)
  metadata_num <- data.frame(val = rnorm(10))
  metadata_chr <- data.frame(grp = rep(c("a", "b"), 5))

  out_num <- pca3d_prepare_data(pca, dims = 1:3, metadata = metadata_num, color_by = "val")
  out_chr <- pca3d_prepare_data(pca, dims = 1:3, metadata = metadata_chr, color_by = "grp")

  expect_true(is.numeric(out_num$color_values))
  expect_true(is.character(out_chr$color_values))
})

test_that("variance caption lists percent variance explained for each dim", {
  pca <- make_pca(p = 4)
  caption <- pca3d_variance_caption(pca, dims = 1:3)

  expect_match(caption, "^PC1 \\(\\d+\\.\\d%\\) . PC2 \\(\\d+\\.\\d%\\) . PC3 \\(\\d+\\.\\d%\\)$")
})

make_iris_pca <- function() {
  prcomp(iris[, 1:4], scale. = TRUE)
}

test_that("plot_pca3d returns a ggplot object", {
  pca <- make_iris_pca()
  p <- plot_pca3d(pca)
  expect_s3_class(p, "ggplot")
})

test_that("plot_pca3d adds a variance-explained caption by default", {
  pca <- make_iris_pca()
  p <- plot_pca3d(pca)
  expect_match(p$labels$caption, "^PC1 \\(")
})

test_that("var_explained = FALSE omits the caption", {
  pca <- make_iris_pca()
  p <- plot_pca3d(pca, var_explained = FALSE)
  expect_null(p$labels$caption)
})

test_that("color_by accepts an unquoted metadata column and maps colour", {
  pca <- make_iris_pca()
  p <- plot_pca3d(pca, metadata = iris, color_by = Species)
  expect_true("colour" %in% names(p$mapping) || "colour" %in% names(p$layers[[1]]$mapping))
})

test_that("color_by accepts a string column name", {
  pca <- make_iris_pca()
  p <- plot_pca3d(pca, metadata = iris, color_by = "Species")
  expect_s3_class(p, "ggplot")
})

test_that("dims argument selects the requested components", {
  pca <- make_iris_pca()
  p_default <- plot_pca3d(pca, theta = 0, phi = 0)
  p_dims <- plot_pca3d(pca, dims = c(2, 3, 4), theta = 0, phi = 0)

  expect_equal(p_default$data$x, unname(pca$x[, 1]))
  expect_equal(p_dims$data$x, unname(pca$x[, 2]))
})

